+// API keys, roles and the audit log. Pure rules over the store; the HTTP layer
+// passes in the time and the request details.
+import { AppError } from "../errors.js";
+
+/** Roles from least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Routes (METHOD + pattern) a cook may call besides reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Routes only managers may call, even though they are reads.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The API key record for an `Authorization: Bearer <key>` header, or throws `unauthorized`. */
+export function authenticate(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(typeof header === "string" ? header.trim() : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless `apiKey`'s role may call `method` on route `pattern`. */
+export function authorize(apiKey, method, pattern) {
+  const route = `${method} ${pattern}`;
+  const role = apiKey.role;
+  const allowed =
+    role === "manager" ||
+    (role === "viewer" && method === "GET" && !MANAGER_READS.has(route)) ||
+    (role === "cook" && ((method === "GET" && !MANAGER_READS.has(route)) || COOK_ROUTES.has(route)));
+  if (!allowed) throw new AppError("forbidden", { role: String(role), action: route });
+}
+
+/** Appends an audit entry (time, key name, method, path, status). */
+export function recordAudit(store, { at, name, method, path, status }) {
+  store.data.audit.push({ at, name, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
